sys_script_include.script:
var ERTriagePatientAjax = Class.create();
ERTriagePatientAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

  createPatient: function() {
    if (!gs.hasRole('x_2206627_er_tri_0.intake'))
      return JSON.stringify({ ok: false, error: 'Not authorized' });

    var first = (this.getParameter('sysparm_first') || '').trim();
    var last = (this.getParameter('sysparm_last') || '').trim();
    var dob = (this.getParameter('sysparm_dob') || '').trim();
    var sex = (this.getParameter('sysparm_sex') || '').trim();
    if (!first || !last || !dob)
      return JSON.stringify({ ok: false, error: 'First name, last name and date of birth are required' });

    var p = new GlideRecord('x_2206627_er_tri_0_patient');
    p.initialize();
    p.setValue('patient_first_name', first);
    p.setValue('patient_last_name', last);
    p.setValue('date_of_birth', dob);
    if (sex) p.setValue('sex', sex);
    var id = p.insert();
    if (!id)
      return JSON.stringify({ ok: false, error: 'Could not create the patient' });

    return JSON.stringify({ ok: true, sys_id: id, display: last + ', ' + first });
  },

  type: 'ERTriagePatientAjax'
});
